const createClient = (respond: (calls: QueryCall) => unknown) => {
  const queries: QueryCall[] = [];
  const from = () => {
    const calls: QueryCall = [];
    queries.push(calls);
    const builder: Record<string, unknown> = {};
    for (const method of [
      "select",
      "eq",
      "neq",
      "in",
      "overlaps",
      "order",
      "range",
    ]) {
      builder[method] = (...args: unknown[]) => {
        calls.push({ method, args });
        return builder;
      };
    }
    // getAllPages refuses a query whose URL has no order clause.
    Object.defineProperty(builder, "url", {
      get: () => ({ search: hasCall(calls, "order", "id") ? "?order=id" : "" }),
    });
    builder.maybeSingle = () => Promise.resolve(respond(calls));
    builder.then = (resolve: (value: unknown) => unknown) =>
      resolve(respond(calls));
    return builder;
  };
  return { client: { from } as unknown as DGSupabaseClient, queries };
};

const hasCall = (calls: QueryCall, method: string, ...args: unknown[]) =>
